"""Customer managed Pulumi deployment agent pool running on the shared EKS cluster (Python)."""

import pulumi
import pulumi_kubernetes as k8s
import pulumi_pulumiservice as pulumiservice

from agent import WorkflowAgent
from mirror import ImageMirror

config = pulumi.Config()
agent_namespace = config.get("agentNamespace") or "pulumi-deployment-agents-py"
pool_name = config.get("poolName") or f"{pulumi.get_project()}-{pulumi.get_stack()}"

# Customer managed deployment pool registered in Pulumi Cloud. The pool token is
# generated by the service and passed directly to the agents running in the cluster.
agent_pool = pulumiservice.AgentPool(
    "agent-pool",
    organization_name=pulumi.get_organization(),
    name=pool_name,
    description="Customer managed deployment agents (Python) running on the shared EKS cluster.",
)

# Target the shared EKS cluster. The kubeconfig is supplied by the
# shared-infra/k8s-cluster ESC environment (sourced from the shared-dev-eks/dev stack).
k8s_provider = k8s.Provider(
    "shared-eks", kubeconfig=config.require_secret("kubeconfig")
)

ns = k8s.core.v1.Namespace(
    "agent-namespace",
    metadata={"name": agent_namespace},
    opts=pulumi.ResourceOptions(provider=k8s_provider),
)

# The images published by Pulumi are mirrored into private ECR so the nodes pull them from
# ECR (via the node role) instead of Docker Hub / ECR Public. Versions are pinned.
# Repository names use a -py prefix so they do not collide with the TypeScript pool project.
agent_version = config.get("agentVersion") or "v2.2.0"
executor_version = config.get("executorVersion") or "3.268.0"
mirror_opts = pulumi.ResourceOptions(providers=[k8s_provider])

# Agent image: also used for the init container of every runner pod.
agent_image = ImageMirror(
    "agent-image",
    source_image=f"docker.io/pulumi/customer-managed-workflow-agent:{agent_version}",
    repository_name="pulumi-deployments-py/customer-managed-workflow-agent",
    tag=agent_version,
    namespace=ns.metadata.name,
    opts=mirror_opts,
)

# Executor image: runs the Pulumi CLI and the Python runtime for each deployment. Set it on
# stacks that use this pool (stack deployment setting "executor image"). Python only; stacks
# in other languages need their own mirrored executor image.
executor_image = ImageMirror(
    "executor-image",
    source_image=f"public.ecr.aws/pulumi/pulumi-python:{executor_version}",
    repository_name="pulumi-deployments-py/executor-python",
    tag=executor_version,
    namespace=ns.metadata.name,
    opts=mirror_opts,
)

# Run the workflow agent from the ECR mirror. Waits for the copy job to finish first.
agent = WorkflowAgent(
    "workflow-agent",
    namespace=ns.metadata.name,
    image=agent_image.image_uri,
    image_pull_policy=config.get("agentImagePullPolicy") or "IfNotPresent",
    replicas=config.get_int("agentReplicas") or 2,
    agent_pool_token=agent_pool.token_value,
    service_url=config.get("serviceUrl") or "https://api.pulumi.com",
    # The shared cluster uses t3.medium nodes (~3.2 GiB allocatable memory), so the
    # default runner request (~4 GB) can never schedule. Size runners to fit.
    runner_cpus=config.get_float("runnerCpus") or 1,
    runner_memory_gb=config.get_float("runnerMemoryGb") or 2,
    opts=pulumi.ResourceOptions(provider=k8s_provider, depends_on=[agent_image]),
)

pulumi.export("poolId", agent_pool.agent_pool_id)
pulumi.export("poolDisplayName", agent_pool.name)
pulumi.export("namespace", ns.metadata.name)
pulumi.export("agentDeploymentName", agent.deployment.metadata.name)
pulumi.export("agentImageUri", agent_image.image_uri)
pulumi.export("executorImageUri", executor_image.image_uri)
